// AYieldStrategy.sol L183-L193 — setClient does NOT zero setAsideBufferSize
function setClient(address client, bool _auth) external override onlyOwner {
    require(client != address(0), ...);
    if (_auth) { _authorizedClients.add(client); } else { _authorizedClients.remove(client); }
    emit ClientAuthorizationSet(client, _auth);
}
