    uint256 buf = underlyingReceived * bufferShares[i] / totalShares;
    if (buf == 0) continue;
    totalSetAside += buf;
    underlyingToken.safeTransfer(clients[i], buf); // <-- no event
}
toRecipient = underlyingReceived - totalSetAside;
